	@Test
	void namedPathEndpointsKeepGraphDomainSemanticsAcrossNullableAndNestedPaths() throws Exception {
		List<String> paths = List.of("<urn:edge>*", "<urn:edge>?", "^<urn:edge>*",
				"(<urn:edge>|<urn:other>)*", "(<urn:edge>?/<urn:other>?)", "((^<urn:edge>)?)*");
		for (boolean sparql : List.of(false, true)) {
			try (Harness harness = new Harness(sparql)) {
				for (String path : paths) {
					for (Value value : List.of(VF.createIRI("urn:absent"), VF.createIRI("urn:a"),
							VF.createIRI("urn:unrelated"), VF.createLiteral("first"), VF.createLiteral("absent"))) {
						harness.assertMatches("SELECT ?s ?o WHERE {?s " + path + " ?o}", Map.of("s", value));
						harness.assertMatches("SELECT ?s ?o WHERE {?s " + path + " ?o}", Map.of("o", value));
						harness.assertMatches("SELECT ?s ?o WHERE {?s " + path + " ?o}",
								Map.of("s", value, "o", value));
						harness.assertMatches("SELECT ?s WHERE {?s " + path + " ?s}", Map.of("s", value));
					}
					for (Value value : List.of(VF.createIRI("urn:absent"), VF.createLiteral("first"),
							VF.createLiteral("absent"))) {
						harness.assertMatches("SELECT ?s WHERE {VALUES ?s {<urn:a>} FILTER EXISTS {?x "
								+ path + " ?o}}", Map.of("x", value));
						harness.assertMatches("SELECT ?s WHERE {VALUES ?s {<urn:a>} FILTER EXISTS {?o "
								+ path + " ?x}}", Map.of("x", value));
					}
					harness.assertMatches("SELECT ?o WHERE {\"absent\" " + path + " ?o}", Map.of());
				}
			}
		}
	}

