	@Test
	void directPreparedServiceRetainsParameterIdentityForOneAndTwoRuntimeRows() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				Value parameter = harness.service("SELECT ?node WHERE {<urn:a> <urn:node> ?node}", Map.of())
						.get(0)
						.getValue("node");
				assertThat(parameter).isInstanceOf(RemoteBNode.class);
				MapBindingSet parameters = new MapBindingSet();
				parameters.addBinding("x", parameter);
				TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
						"SELECT ?copy WHERE {SERVICE <urn:endpoint> {BIND(?x AS ?copy)}}", null).getTupleExpr();
				new BindingAssignerOptimizer().optimizeForPreparedQuery(expression, parameters);
				AtomicReference<Service> found = new AtomicReference<>();
				expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Service service) {
						found.set(service);
					}
				});
				Service logical = found.get();
				Service snapshot = logical.clone();
				String source = logical.getServiceExpressionString();
				assertAll(List.of(1, 2).stream().map(count -> () -> {
					List<BindingSet> inputs = Collections.nCopies(count, EmptyBindingSet.getInstance());
					List<BindingSet> actual = new ArrayList<>();
					try (var rows = harness.endpoint.evaluate(logical,
							new CloseableIteratorIteration<>(inputs.iterator()), null)) {
						while (rows.hasNext()) {
							actual.add(rows.next());
						}
					}
					assertThat(logical).isEqualTo(snapshot);
					assertThat(logical.getServiceExpressionString()).isEqualTo(source);
					assertThat(logical.getPreparedInputBindings().get("x")).isSameAs(parameter);
					assertThat(actual).as("direct adapter=%s input rows=%s", sparql, count).hasSize(count);
					assertThat(actual).allSatisfy(row -> {
						assertThat(row.getBindingNames()).containsExactly("copy");
						assertThat(row.getValue("copy")).isSameAs(parameter);
					});
				}));
			}
		}));
	}

	@Test
	void directCanonicalAskExecutesTheTrustedIdentityThroughBothAdapters() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				Value alias = harness.service("SELECT ?node WHERE {<urn:a> <urn:node> ?node}", Map.of())
						.get(0)
						.getValue("node");
				assertThat(alias).isInstanceOf(RemoteBNode.class);
				Service logical = preparedService("<urn:a> <urn:node> ?node", Map.of());
				Service snapshot = logical.clone();
				MapBindingSet input = new MapBindingSet();
				input.addBinding("node", alias);
				BNode unrelated = VF.createBNode("member");
				input.addBinding("local", unrelated);
				assertThat(harness.endpoint.ask(logical, input, null)).isTrue();
				assertThat(input.getBindingNames()).containsExactlyInAnyOrder("node", "local");
				assertThat(input.getValue("node")).isSameAs(alias);
				assertThat(input.getValue("local")).isSameAs(unrelated);

				Value absent = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF,
						harness.endpoint.getBNodeIdentityScope(), true).map(VF.createBNode("absent-canonical-node"));
				MapBindingSet missing = new MapBindingSet();
				missing.addBinding("node", absent);
				assertThat(harness.endpoint.ask(logical, missing, null)).isFalse();
				assertThat(missing.getValue("node")).isSameAs(absent);
				Value foreign = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, new Object(), true)
						.map(VF.createBNode("member"));
				int requests = harness.requests.size();
				assertAll(List.<Value>of(unrelated, foreign).stream().map(unsupported -> () -> {
					MapBindingSet untrusted = new MapBindingSet();
					untrusted.addBinding("node", unsupported);
					assertThatThrownBy(() -> harness.endpoint.ask(logical, untrusted, null))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining("Unsupported blank-node identity");
					assertThat(untrusted.getValue("node")).isSameAs(unsupported);
					assertThat(harness.requests).hasSize(requests);
				}));
				harness.endpoint.setCanonicalBNodeIDsSupported(false);
				assertThatThrownBy(() -> harness.endpoint.ask(logical, input, null))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessageContaining("Unsupported blank-node identity");
				assertThat(harness.requests).hasSize(requests);
				assertThat(input.getValue("node")).isSameAs(alias);
				assertThat(input.getValue("local")).isSameAs(unrelated);
				assertThat(logical).isEqualTo(snapshot);
			}
		}));
	}

