	@Test
	void conflictingFixedOutputRetainsOtherCorrelatedInputsAndErrorModes() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			assertAll(List.of(false, true).stream().map(silent -> () -> {
				try (Harness harness = new Harness(sparql)) {
					Service logical = preparedService("?x <urn:p> ?o FILTER(?gate = \"required\")",
							Map.of("x", VF.createIRI("urn:a")), silent);
					Service snapshot = logical.clone();
					Value callerNode = VF.createBNode("caller-local");
					Value gate = VF.createLiteral("required");
					MutableBindingSet input = GraphFrameBindings.supply(new MapBindingSet(), "graphParameter",
							VF.createIRI("urn:outer-graph"));
					input.addBinding("x", callerNode);
					input.addBinding("gate", gate);
					input.addBinding("keep", VF.createLiteral("caller"));
					doAnswer(invocation -> {
						BindingSet actualInput = invocation.getArgument(2);
						assertThat(actualInput.getValue("gate")).isSameAs(gate);
						assertThat(actualInput.hasBinding("x")).isFalse();
						assertThat(GraphFrameBindings.isSupplied(RemoteBNode.originalBindings(actualInput),
								"graphParameter"))
										.isTrue();
						throw new QueryEvaluationException("endpoint failure for " + actualInput.getValue("gate"));
					}).when(harness.endpoint).select(any(), any(), any(), nullable(String.class));
					if (silent) {
						List<BindingSet> actual = new ArrayList<>();
						try (var rows = harness.endpoint.evaluate(logical,
								new CloseableIteratorIteration<>(List.<BindingSet>of(input).iterator()), null)) {
							while (rows.hasNext()) {
								actual.add(rows.next());
							}
						}
						assertThat(actual).containsExactly(input);
						assertThat(actual.get(0).getValue("x")).isSameAs(callerNode);
					} else {
						assertThatThrownBy(() -> {
							try (var rows = harness.endpoint.evaluate(logical,
									new CloseableIteratorIteration<>(List.<BindingSet>of(input).iterator()), null)) {
								rows.hasNext();
							}
						}).hasMessageContaining("endpoint failure for").hasMessageContaining("required");
					}
					verify(harness.endpoint).select(any(), any(), any(), nullable(String.class));
					assertThat(logical).isEqualTo(snapshot);
				}
			}));
		}));
	}

