	@Test
	void blockSizeOnePreservesOriginalEndpointFailureAndSilentCallerBag() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			assertAll(List.of(false, true).stream().map(silent -> () -> {
				assertAll(List.of(0, 1, 2).stream().map(mode -> () -> {
					try (Harness harness = new Harness(sparql)) {
						harness.endpoint.setBoundJoinBlockSize(1);
						harness.endpoint.setPartitionToleranceDeclared(false);
						Service logical = preparedService("?x <urn:p> ?o FILTER(?gate = \"allow\")",
								Map.of("x", VF.createIRI("urn:a")), silent);
						Service snapshot = logical.clone();
						List<BindingSet> inputs = fallbackInputs(mode);
						doAnswer(invocation -> {
							assertThat((BindingSet) invocation.getArgument(2)).isEmpty();
							throw new QueryEvaluationException("original independent endpoint failure");
						}).when(harness.endpoint).select(any(), any(), any(), nullable(String.class));
						if (silent) {
							List<BindingSet> actual = new ArrayList<>();
							try (var rows = harness.endpoint.evaluate(logical,
									new CloseableIteratorIteration<>(inputs.iterator()), null)) {
								while (rows.hasNext()) {
									actual.add(rows.next());
								}
							}
							assertThat(actual).containsExactlyElementsOf(inputs);
							for (int index = 0; index < inputs.size(); index++) {
								assertThat(actual.get(index).getValue("x")).isSameAs(inputs.get(index).getValue("x"));
							}
						} else {
							assertThatThrownBy(() -> {
								try (var rows = harness.endpoint.evaluate(logical,
										new CloseableIteratorIteration<>(inputs.iterator()), null)) {
									rows.hasNext();
								}
							}).hasMessageContaining("original independent endpoint failure");
						}
						verify(harness.endpoint).select(any(), any(), any(), nullable(String.class));
						assertThat(logical).isEqualTo(snapshot);
					}
				}));
			}));
		}));
	}

	private static List<BindingSet> fallbackInputs(int mode) {
		List<BindingSet> rows = new ArrayList<>();
		for (int index = 0; index < 2; index++) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("x", mode == 1 || mode == 2 && index == 0
					? VF.createBNode("caller-" + index)
					: VF.createIRI("urn:a"));
			row.addBinding("gate", VF.createLiteral("allow"));
			row.addBinding("keep", VF.createLiteral(index));
			rows.add(row);
		}
		return rows;
	}

	@Test
	void localAliasedValuesBeforeCapturedRelationHaveExplicitBags() throws Exception {
		assertLocalAliasedValuesBags(true);
	}

	@Test
	void localAliasedValuesAfterCapturedRelationHaveExplicitBags() throws Exception {
		assertLocalAliasedValuesBags(false);
	}

	private static void assertLocalAliasedValuesBags(boolean before) throws Exception {
		MapBindingSet first = new MapBindingSet();
		first.addBinding("x", VF.createIRI("urn:a"));
		first.addBinding("o", VF.createLiteral("first"));
		MapBindingSet graph = new MapBindingSet();
		graph.addBinding("x", VF.createIRI("urn:a"));
		graph.addBinding("o", VF.createLiteral("graph"));
		MapBindingSet second = new MapBindingSet();
		second.addBinding("x", VF.createIRI("urn:b"));
		second.addBinding("o", VF.createLiteral("second"));
		// A preceding projection owns x, even when its alias is absent. A following projection is instead
		// overwritten by the still-active API capture in the statement pattern. Each a matches both p rows.
		List<BasicGraphPatternCase> cases = before ? List.of(
				new BasicGraphPatternCase("<urn:a>", List.of(first, graph)),
				new BasicGraphPatternCase("<urn:b>", List.of(second)),
				new BasicGraphPatternCase("<urn:a> <urn:b> <urn:a>", List.of(first, graph, second, first, graph)),
				new BasicGraphPatternCase("UNDEF", List.of(first, graph, second)),
				new BasicGraphPatternCase("<urn:a> UNDEF", List.of(first, graph, first, graph, second)))
				: List.of(
						new BasicGraphPatternCase("<urn:a>", List.of(first, graph)),
						new BasicGraphPatternCase("<urn:b>", List.of(first, graph)),
						new BasicGraphPatternCase("<urn:a> <urn:b> <urn:a>",
								List.of(first, graph, first, graph, first, graph)),
						new BasicGraphPatternCase("UNDEF", List.of(first, graph)),
						new BasicGraphPatternCase("<urn:a> UNDEF", List.of(first, graph, first, graph)));
		try (Harness harness = new Harness(false)) {
			assertAll(cases.stream().map(test -> () -> {
				String alias = "{SELECT (?v AS ?x) WHERE {VALUES ?v {" + test.body() + "}}}";
				String relation = "?x <urn:p> ?o";
				String body = before ? alias + " " + relation : relation + " " + alias;
				List<BindingSet> actual = Harness.evaluate(harness.data, "SELECT ?x ?o WHERE {" + body + "}",
						Map.of("x", VF.createIRI("urn:a")));
				assertThat(actual).as("local alias before=%s body=%s", before, body)
						.containsExactlyInAnyOrderElementsOf(test.expected());
			}));
		}
	}

	@Test
	void aliasedValuesAroundCapturedRelationsUseTheSameServiceBoundaryOracle() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				assertAll(List.of("<urn:a>", "<urn:b>", "<urn:a> <urn:b> <urn:a>", "UNDEF", "<urn:a> UNDEF")
						.stream()
						.map(values -> () -> {
							assertAll(List.of(false, true).stream().map(before -> () -> {
								String alias = "{SELECT (?v AS ?x) WHERE {VALUES ?v {" + values + "}}}";
								String relation = "?x <urn:p> ?o";
								String body = before ? alias + " " + relation : relation + " " + alias;
								Map<String, Value> parameters = Map.of("x", VF.createIRI("urn:a"));
								List<BindingSet> expected = Harness.evaluate(harness.data,
										"SELECT ?x ?o WHERE {" + body + "}", parameters);
								String query = "SELECT ?x ?o WHERE {SERVICE <urn:endpoint> {" + body + "}}";
								if (!before && values.contains("<urn:b>")) {
									// The local capture overwrites the following projected x. A remote ordinary
									// join cannot reproduce that overwrite with conflicting exported values.
									assertThat(expected).hasSize(values.equals("<urn:b>") ? 2 : 6);
									harness.assertUnsupportedOverwrite(query, parameters);
								} else {
									List<BindingSet> actual = Harness.evaluate(harness.sender, query, parameters);
									assertThat(actual).as("adapter=%s alias before=%s body=%s", sparql, before, body)
											.containsExactlyInAnyOrderElementsOf(expected);
								}
							}));
						}));
			}
		}));
	}

	@Test
	void unknownAfterAliasOutputIsRejectedWhileItsBeforeOrderShadowsTheApiParameter() {
		assertAll(List.of(false, true).stream().map(sparql -> () -> {
			try (Harness harness = new Harness(sparql)) {
				assertAll(List.of(false, true).stream().map(before -> () -> {
					String alias = "{SELECT (STR(?v) AS ?x) WHERE {VALUES ?v {1}}}";
					String relation = "?x <urn:p> ?o";
					String body = before ? alias + " " + relation : relation + " " + alias;
					Map<String, Value> parameters = Map.of("x", VF.createIRI("urn:a"));
					MapBindingSet first = new MapBindingSet();
					first.addBinding("x", VF.createIRI("urn:a"));
					first.addBinding("o", VF.createLiteral("first"));
					MapBindingSet graph = new MapBindingSet();
					graph.addBinding("x", VF.createIRI("urn:a"));
					graph.addBinding("o", VF.createLiteral("graph"));
					List<BindingSet> expected = before ? List.of() : List.of(first, graph);
					assertThat(Harness.evaluate(harness.data, "SELECT ?x ?o WHERE {" + body + "}", parameters))
							.as("local scalar alias before=%s body=%s", before, body)
							.containsExactlyInAnyOrderElementsOf(expected);
					String query = "SELECT ?x ?o WHERE {SERVICE <urn:endpoint> {" + body + "}}";
					if (before) {
						assertThat(Harness.evaluate(harness.sender, query, parameters)).isEmpty();
					} else {
						// The bounded proof does not evaluate STR to discover its produced RDF value.
						harness.assertUnsupportedOverwrite(query, parameters);
					}
				}));
			}
		}));
	}

