	private static final class OpaqueBindingContract extends UnaryTupleOperator implements BindingAnalysisContract {
		OpaqueBindingContract(TupleExpr argument) {
			super(argument);
		}

		@Override
		public Class<? extends QueryModelNode> bindingContractClass() {
			return OpaqueBindingContract.class;
		}

		@Override
		public OutputFacts bindingOutput(QueryAlgebraBindingAnalysis analysis, ReadOnlyContext input) {
			return analysis.outputFacts(getArg(), input);
		}

		@Override
		public ReadOnlyContext bindingInput(QueryAlgebraBindingAnalysis analysis, QueryModelNode child,
				ReadOnlyContext input) {
			return input;
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}
	}

